from dataclasses import dataclass
from typing import Any, Optional


@dataclass
class OrderResult:
    order_id: Any
    total: float
    user_id: Any


def validate_order(order: Any) -> bool:
    if order is None:
        return False
    if order['status'] != 'pending':
        return False
    items = order['items']
    if items is None or len(items) == 0:
        return False
    if order['user_id'] is None:
        return False
    for item in items:
        if item['price'] is None or item['quantity'] is None:
            return False
    return True


def process_order(order: Any) -> Optional[OrderResult]:
    if not validate_order(order):
        return None
    total = sum(item['price'] * item['quantity'] for item in order['items'])
    return OrderResult(
        order_id=order['id'],
        total=total,
        user_id=order['user_id']
    )
